/* RASEEN — Island Game Frontend (app.min.js)
 *   • Telegram WebApp + Cloudflare Worker API
 *   • Home   : Island grid (Empty/Occupied/Locked), Income/Offline/Slots, Collect
 *   • Build  : Buy Assets + Upgrade Assets tabs
 *   • Friends: Referral link + list
 *   • Wallet : Deposit + Withdraw
 */
(function () {
  // ── Config ────────────────────────────────────────────────────
  var API_URL  = "https://silent-block-bedf.ahmedrabieharoun.workers.dev/api";
  var BOT_USER = "YourBotUsername"; // ← change (no @)
  var TITLE    = "Island King";
  var VIEWPORT = "width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover";

  // Asset visual (emoji until real PNG icons are wired)
  var ASSET_ICON = { coconut:"🌴", banana:"🍌", fishing:"🎣" };

  // ── Head ──────────────────────────────────────────────────────
  document.title = TITLE;
  var vp = document.querySelector('meta[name="viewport"]');
  if (!vp) { vp = document.createElement('meta'); vp.name = 'viewport'; document.head.appendChild(vp); }
  vp.setAttribute('content', VIEWPORT);
  if (!window.Telegram || !window.Telegram.WebApp) {
    var s = document.createElement('script');
    s.src = 'https://telegram.org/js/telegram-web-app.js';
    document.head.appendChild(s);
  }

  // ── Styles ────────────────────────────────────────────────────
  var CSS =
    "*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}" +
    ":root{--sky:#1c6aa6;--sky2:#3597d9;--sand:#f5e7c1;--card:#fefcf5;--ink:#0f2438;--muted:#5a6d80;--green:#3a8a2a;--green2:#5cb432;--coin:#f5b316;--ton:#0098ea;--red:#e44e4e;--lock:#94a3b0}" +
    "html,body{background:#0a2238;color:var(--ink)}" +
    "body{font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;min-height:100vh;padding:0 0 78px;font-size:14px}" +

    /* topbar */
    ".topbar{display:flex;align-items:center;gap:8px;padding:10px 12px;background:linear-gradient(180deg,#1d5b8c,#1c6aa6);color:#fff;position:sticky;top:0;z-index:5}" +
    ".av{width:42px;height:42px;border-radius:50%;background:#0a2238;border:2px solid #fff;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:20px;flex:none}" +
    ".av img{width:100%;height:100%;object-fit:cover}" +
    ".uname{font-weight:700;font-size:14px;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}" +
    ".chip{display:flex;align-items:center;gap:6px;background:rgba(0,0,0,.25);border-radius:20px;padding:5px 10px;font-weight:700;font-size:13px;color:#fff}" +
    ".chip .ico{font-size:14px}" +
    ".chip.coin{background:rgba(245,179,22,.25);border:1px solid rgba(245,179,22,.5)}" +
    ".chip.ton{background:rgba(0,152,234,.22);border:1px solid rgba(0,152,234,.55)}" +

    /* sections */
    ".sec{display:none}.sec.active{display:block}" +
    "#secHome{background:linear-gradient(180deg,#3597d9 0%,#1c6aa6 100%);min-height:calc(100vh - 130px)}" +

    /* stats card */
    ".stats{margin:10px 12px;background:var(--card);border-radius:14px;padding:10px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;box-shadow:0 4px 12px rgba(0,0,0,.18)}" +
    ".stat{display:flex;flex-direction:column;align-items:flex-start;padding:6px 8px;border-right:1px solid #e8ddc2}" +
    ".stat:last-child{border-right:none}" +
    ".stat .lbl{font-size:11px;color:var(--muted);font-weight:600;display:flex;align-items:center;gap:4px}" +
    ".stat .val{font-size:16px;font-weight:800;color:var(--ink);margin-top:2px}" +
    ".stat .small{font-size:11px;font-weight:600;color:var(--muted)}" +
    ".upg{margin-top:4px;background:linear-gradient(180deg,var(--green2),var(--green));color:#fff;border:none;border-radius:8px;padding:4px 10px;font-size:11px;font-weight:700;cursor:pointer}" +

    /* island grid */
    ".island{margin:8px 12px;background:linear-gradient(180deg,#f0d896,#dcb764);border:4px solid #b58b3e;border-radius:24px;padding:14px;box-shadow:0 6px 20px rgba(0,0,0,.25)}" +
    ".grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}" +
    ".slot{aspect-ratio:1;border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;position:relative;overflow:hidden;border:2px dashed rgba(255,255,255,.55);background:linear-gradient(180deg,#7fcb52,#5ba83a);color:#fff;text-align:center;padding:4px}" +
    ".slot.occupied{border:2px solid #6e4a1f;background:linear-gradient(180deg,#9bda6f,#5ba83a);cursor:pointer}" +
    ".slot.locked{border:2px solid #4a5a68;background:linear-gradient(180deg,#7a8a98,#56636f);cursor:not-allowed;color:#dde}" +
    ".slot .plus{font-size:30px;font-weight:800;color:#fff;text-shadow:0 2px 0 rgba(0,0,0,.2)}" +
    ".slot .em{font-size:30px;line-height:1;margin-bottom:2px}" +
    ".slot .lv{font-size:10px;font-weight:800;background:rgba(0,0,0,.45);color:#fff;padding:1px 5px;border-radius:6px;margin-top:2px}" +
    ".slot .ih{font-size:10px;font-weight:700;background:rgba(0,0,0,.55);color:#ffd;padding:1px 5px;border-radius:6px;margin-top:2px}" +

    /* collect */
    ".collect-wrap{margin:14px 16px 6px;display:flex;flex-direction:column;align-items:center}" +
    ".collect{width:100%;max-width:280px;background:linear-gradient(180deg,#f5b316,#d6921a);border:3px solid #a26b0e;color:#fff;border-radius:18px;padding:12px;font-weight:800;font-size:18px;cursor:pointer;text-align:center;box-shadow:0 6px 14px rgba(0,0,0,.25)}" +
    ".collect:disabled{filter:grayscale(.4);cursor:default}" +
    ".collect .sub{display:block;font-size:13px;margin-top:2px;font-weight:700}" +

    /* nav */
    ".nav{position:fixed;bottom:0;left:0;right:0;display:flex;background:#0a2238;border-top:1px solid rgba(255,255,255,.08);z-index:10}" +
    ".nav-item{flex:1;padding:8px 4px;text-align:center;cursor:pointer;color:#7a90a8;font-size:11px;font-weight:700}" +
    ".nav-item.active{color:#f5b316}" +
    ".nav-ico{font-size:20px;margin-bottom:2px;display:block}" +

    /* generic cards (wallet/friends/buildings) */
    ".page{padding:12px;color:var(--ink);background:#eef3f8;min-height:calc(100vh - 130px)}" +
    ".card{background:#fff;border-radius:14px;padding:14px;margin-bottom:12px;box-shadow:0 2px 8px rgba(0,0,0,.06)}" +
    ".h{font-size:15px;font-weight:800;margin-bottom:10px;color:var(--ink);display:flex;align-items:center;gap:6px}" +
    ".row{display:flex;align-items:center;gap:10px;justify-content:space-between;padding:8px 0;border-bottom:1px solid #eef0f3}.row:last-child{border-bottom:none}" +
    ".lbl{color:var(--muted);font-size:12px}.val{font-weight:700}" +
    "input,textarea{width:100%;background:#f5f7fa;border:1px solid #dde3ea;border-radius:10px;padding:10px 12px;color:var(--ink);font-size:14px;font-family:inherit;margin-bottom:10px}" +
    "input:focus,textarea:focus{outline:none;border-color:var(--green2)}" +
    "button.btn{width:100%;background:linear-gradient(180deg,var(--green2),var(--green));border:none;border-radius:12px;padding:12px;color:#fff;font-weight:800;font-size:14px;cursor:pointer;font-family:inherit}" +
    "button.btn:disabled{opacity:.5;cursor:default}" +
    "button.btn.ghost{background:#fff;border:1px solid #dde3ea;color:var(--ink)}" +
    ".msg{padding:10px 12px;border-radius:10px;margin-bottom:10px;font-size:13px;font-weight:600}" +
    ".msg.err{background:#fde7e7;color:#a3262b}" +
    ".msg.ok{background:#e6f5e0;color:#246b18}" +
    ".empty{text-align:center;color:var(--muted);padding:20px;font-size:13px}" +
    ".hist-row{display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #eef0f3;font-size:12px}.hist-row:last-child{border-bottom:none}" +
    ".badge{padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700}" +
    ".badge.ok{background:#e6f5e0;color:#246b18}" +
    ".badge.pend{background:#fff2cc;color:#8a6b00}" +
    ".badge.err{background:#fde7e7;color:#a3262b}" +
    ".tabs{display:flex;gap:6px;background:#eef3f8;border-radius:12px;padding:5px;margin-bottom:12px}" +
    ".tab{flex:1;padding:10px;text-align:center;font-weight:800;font-size:13px;border-radius:9px;color:var(--muted);cursor:pointer}" +
    ".tab.active{background:linear-gradient(180deg,var(--green2),var(--green));color:#fff}" +
    ".asset-row{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #eef0f3}.asset-row:last-child{border-bottom:none}" +
    ".asset-ico{width:54px;height:54px;border-radius:12px;background:#f5e7c1;display:flex;align-items:center;justify-content:center;font-size:28px;flex:none}" +
    ".asset-info{flex:1;min-width:0}" +
    ".asset-name{font-weight:800;font-size:14px;color:var(--ink)}" +
    ".asset-meta{font-size:12px;color:var(--muted);margin-top:2px}" +
    ".price-btn{background:linear-gradient(180deg,var(--green2),var(--green));border:none;color:#fff;padding:8px 14px;border-radius:18px;font-weight:800;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:5px}" +
    ".price-btn:disabled{filter:grayscale(.5);opacity:.7;cursor:default}" +
    ".loader{display:flex;align-items:center;justify-content:center;min-height:60vh;color:#fff}" +

    /* modal */
    ".modal{position:fixed;inset:0;background:rgba(0,0,0,.55);display:none;align-items:center;justify-content:center;z-index:50;padding:20px}" +
    ".modal.open{display:flex}" +
    ".modal-card{background:#fff;border-radius:18px;max-width:340px;width:100%;padding:18px;position:relative}" +
    ".modal-title{font-weight:800;font-size:16px;text-align:center;margin-bottom:12px;color:var(--ink)}" +
    ".modal-close{position:absolute;top:10px;right:12px;background:none;border:none;font-size:22px;cursor:pointer;color:var(--muted)}" +
    ".pick-list{display:flex;flex-direction:column;gap:8px;max-height:60vh;overflow:auto}";

  var style = document.createElement('style'); style.textContent = CSS; document.head.appendChild(style);

  // ── HTML shell ────────────────────────────────────────────────
  var HTML = ''
    + '<div class="topbar">'
    +   '<div class="av" id="uAv">👤</div>'
    +   '<div class="uname" id="uName">Player</div>'
    +   '<div class="chip coin"><span class="ico">🪙</span><span id="uCoins">0</span></div>'
    +   '<div class="chip ton"><span class="ico">💎</span><span id="uTon">0</span></div>'
    + '</div>'
    + '<div id="loader" class="loader">Loading…</div>'

    // HOME
    + '<div class="sec" id="secHome">'
    +   '<div class="stats">'
    +     '<div class="stat"><span class="lbl">🪙 Income</span><span class="val" id="hmIncome">0</span><span class="small">/ h</span></div>'
    +     '<div class="stat"><span class="lbl">⏱ Offline</span><span class="val" id="hmOffline">3h</span><button class="upg" id="btnUpgOffline">Upgrade</button></div>'
    +     '<div class="stat"><span class="lbl">🟩 Slots</span><span class="val" id="hmSlots">1/8</span><button class="upg" id="btnUpgSlots">Upgrade</button></div>'
    +   '</div>'
    +   '<div class="island"><div class="grid" id="islandGrid"></div></div>'
    +   '<div class="collect-wrap">'
    +     '<button class="collect" id="btnCollect">Collect<span class="sub">🪙 <span id="pendCoins">0</span></span></button>'
    +   '</div>'
    + '</div>'

    // BUILDINGS
    + '<div class="sec" id="secBuild"><div class="page">'
    +   '<div class="h">🏝️ Buildings</div>'
    +   '<div class="tabs"><div class="tab active" data-bt="buy">Buy Assets</div><div class="tab" data-bt="upg">Upgrade Assets</div></div>'
    +   '<div class="card" id="bldBuyCard"><div id="bldBuy"></div></div>'
    +   '<div class="card" id="bldUpgCard" style="display:none"><div id="bldUpg"></div></div>'
    + '</div></div>'

    // FRIENDS
    + '<div class="sec" id="secRefs"><div class="page">'
    +   '<div class="card"><div class="h">👥 Invite Friends</div>'
    +     '<p style="font-size:12px;color:var(--muted);margin-bottom:10px">Earn <b id="rfPct">10%</b> on every TON deposit your referrals make.</p>'
    +     '<input id="rfLink" type="text" readonly>'
    +     '<button class="btn" id="rfCopy">Copy Invite Link</button>'
    +     '<button class="btn ghost" id="rfShare" style="margin-top:8px">Share via Telegram</button>'
    +   '</div>'
    +   '<div class="card"><div class="h">Your Referrals (<span id="rfCount">0</span>)</div><div id="rfList"><div class="empty">No referrals yet</div></div></div>'
    + '</div></div>'

    // WALLET
    + '<div class="sec" id="secWallet"><div class="page">'
    +   '<div class="card"><div class="h">💎 Wallet</div>'
    +     '<div class="row"><span class="lbl">TON Balance</span><span class="val" id="wTon">0 TON</span></div>'
    +     '<div class="row"><span class="lbl">Coins</span><span class="val" id="wCoins">0</span></div>'
    +     '<div class="row"><span class="lbl">Exchange Rate</span><span class="val" id="wRate">50,000 = 1 TON</span></div>'
    +   '</div>'
    +   '<div class="card"><div class="h">⬇️ Deposit TON</div>'
    +     '<div class="row"><span class="lbl">Send to</span><span class="val" style="font-size:11px;word-break:break-all;text-align:right;max-width:60%" id="dpAddr">SET_DEPOSIT_ADDRESS</span></div>'
    +     '<div class="row"><span class="lbl">Min</span><span class="val" id="dpMin">1 TON</span></div>'
    +     '<input id="dpAmount" type="number" step="0.0001" min="0" placeholder="Amount in TON">'
    +     '<input id="dpHash" type="text" placeholder="Transaction hash">'
    +     '<div id="dpMsg"></div><button class="btn" id="dpBtn">Submit Deposit</button>'
    +   '</div>'
    +   '<div class="card"><div class="h">⬆️ Withdraw TON</div>'
    +     '<div class="row"><span class="lbl">Min</span><span class="val" id="wdMin">0.0001 TON</span></div>'
    +     '<div class="row"><span class="lbl">Fee</span><span class="val" id="wdFee">10%</span></div>'
    +     '<input id="wdAddr" type="text" placeholder="Your TON wallet address">'
    +     '<input id="wdAmount" type="number" step="0.0001" min="0" placeholder="Amount in TON">'
    +     '<div id="wdMsg"></div><button class="btn" id="wdBtn">Request Withdrawal</button>'
    +   '</div>'
    +   '<div class="card"><div class="h">History</div><div id="walletHist"></div></div>'
    + '</div></div>'

    // BOTTOM NAV
    + '<div class="nav">'
    +   '<div class="nav-item active" data-sec="secHome"><span class="nav-ico">🏠</span>Home</div>'
    +   '<div class="nav-item" data-sec="secBuild"><span class="nav-ico">🏗️</span>Buildings</div>'
    +   '<div class="nav-item" data-sec="secRefs"><span class="nav-ico">👥</span>Friends</div>'
    +   '<div class="nav-item" data-sec="secWallet"><span class="nav-ico">💼</span>Wallet</div>'
    + '</div>'

    // MODAL
    + '<div class="modal" id="modal"><div class="modal-card">'
    +   '<button class="modal-close" id="mClose">×</button>'
    +   '<div class="modal-title" id="mTitle">—</div>'
    +   '<div id="mBody"></div>'
    + '</div></div>';

  // ── State + boot ──────────────────────────────────────────────
  var state = { initData:'', user:null, data:null, currentSlot:null, tickIv:null };

  function boot() {
    document.body.innerHTML = HTML;
    bindNav();
    document.getElementById('btnCollect').onclick = doCollect;
    document.getElementById('btnUpgSlots').onclick = function(){ openUpgSlots(); };
    document.getElementById('btnUpgOffline').onclick = function(){ openUpgOffline(); };
    document.getElementById('mClose').onclick = closeModal;
    document.getElementById('modal').onclick = function(e){ if (e.target.id === 'modal') closeModal(); };
    document.querySelectorAll('.tab[data-bt]').forEach(function(t){ t.onclick = function(){
      document.querySelectorAll('.tab[data-bt]').forEach(function(x){ x.classList.remove('active'); });
      t.classList.add('active');
      var bt = t.dataset.bt;
      document.getElementById('bldBuyCard').style.display = bt==='buy' ? '' : 'none';
      document.getElementById('bldUpgCard').style.display = bt==='upg' ? '' : 'none';
    }; });
    document.getElementById('dpBtn').onclick = submitDeposit;
    document.getElementById('wdBtn').onclick = submitWithdraw;
    document.getElementById('rfCopy').onclick = copyInviteLink;
    document.getElementById('rfShare').onclick = shareInviteLink;
    initTg();
  }

  function initTg() {
    var tries = 0;
    var iv = setInterval(function(){
      tries++;
      if (window.Telegram && window.Telegram.WebApp){
        clearInterval(iv);
        try { window.Telegram.WebApp.ready(); window.Telegram.WebApp.expand(); } catch(_){}
        state.initData = window.Telegram.WebApp.initData || '';
        loadState();
      } else if (tries > 40){ clearInterval(iv); loadState(); }
    }, 100);
  }

  function api(action, data){
    return fetch(API_URL, {
      method:'POST',
      headers:{ 'Content-Type':'application/json', 'Authorization':'Telegram '+state.initData, 'X-Action':action },
      body:JSON.stringify({ action:action, data:data || {} }),
    }).then(function(r){ return r.json(); });
  }

  function bindNav(){
    var items = document.querySelectorAll('.nav-item');
    items.forEach(function(el){ el.onclick = function(){
      items.forEach(function(x){ x.classList.remove('active'); });
      el.classList.add('active');
      document.querySelectorAll('.sec').forEach(function(s){ s.classList.remove('active'); });
      document.getElementById(el.dataset.sec).classList.add('active');
    }; });
  }

  function loadState(){
    api('getState', { _initData: state.initData }).then(function(res){
      var loader = document.getElementById('loader');
      if (!res || !res.success){ if (loader) loader.textContent = (res && res.error) || 'Failed to load.'; return; }
      state.data = res.data; state.user = res.data.user;
      if (loader) loader.style.display = 'none';
      document.getElementById('secHome').classList.add('active');
      render();
      if (state.tickIv) clearInterval(state.tickIv);
      state.tickIv = setInterval(tickPending, 1000);
    }).catch(function(e){ var l = document.getElementById('loader'); if (l) l.textContent = 'Network error: ' + e.message; });
  }

  // ── Render ────────────────────────────────────────────────────
  function render(){
    var u    = state.user;
    var d    = state.data;
    var isl  = d.island;
    var cfg  = d.config || {};

    document.getElementById('uName').textContent = (u.firstName || 'Player');
    document.getElementById('uCoins').textContent = fmtNum(u.coins);
    document.getElementById('uTon').textContent   = fmtTon(u.tonBalance);
    var av = document.getElementById('uAv');
    if (u.photoUrl) av.innerHTML = '<img src="' + u.photoUrl + '" alt="">';

    document.getElementById('hmIncome').textContent  = fmtNum(isl.incomePerHour);
    document.getElementById('hmOffline').textContent = u.offlineHours + 'h';
    document.getElementById('hmSlots').textContent   = countOccupied(u.slots) + '/' + u.slotCount;

    renderIsland();
    document.getElementById('pendCoins').textContent = fmtNum(isl.pendingCoins);
    document.getElementById('btnCollect').disabled   = isl.pendingCoins <= 0;

    renderBuy();
    renderUpg();

    // Friends
    document.getElementById('rfPct').textContent   = (cfg.refBonusPct || 10) + '%';
    document.getElementById('rfLink').value        = 'https://t.me/' + BOT_USER + '?start=' + u.referralCode;
    document.getElementById('rfCount').textContent = (d.referrals||[]).length;
    renderRefs(d.referrals || []);

    // Wallet
    document.getElementById('wTon').textContent  = fmtTon(u.tonBalance) + ' TON';
    document.getElementById('wCoins').textContent= fmtNum(u.coins);
    document.getElementById('wRate').textContent = fmtNum(cfg.coinToTon) + ' = 1 TON';
    document.getElementById('dpMin').textContent = (cfg.minDepositTon || 1) + ' TON';
    document.getElementById('wdMin').textContent = (cfg.minWithdrawTon || 0.0001) + ' TON';
    document.getElementById('wdFee').textContent = (cfg.withdrawFeePct || 10) + '%';
    if (u.withdrawWallet) document.getElementById('wdAddr').value = u.withdrawWallet;
    renderWalletHist(d.depHistory || [], d.wdHistory || []);
  }

  function renderIsland(){
    var u = state.user; var grid = document.getElementById('islandGrid');
    var html = '';
    var total = state.data.island.totalPositions;
    var unlocked = state.data.island.unlockedSlots;
    for (var i = 0; i < total; i++){
      var slot = (u.slots || {})[String(i)];
      if (i >= unlocked){
        html += '<div class="slot locked">🔒</div>';
      } else if (slot && slot.type){
        var ic = ASSET_ICON[slot.type] || '🌱';
        var inc = incomeOf(slot.type, slot.level);
        html += '<div class="slot occupied" data-idx="'+i+'" data-act="upg">' +
                '<div class="em">'+ic+'</div>' +
                '<div class="lv">Lv.'+slot.level+'</div>' +
                '<div class="ih">'+fmtNum(inc)+'/h</div>' +
                '</div>';
      } else {
        html += '<div class="slot" data-idx="'+i+'" data-act="buy"><div class="plus">+</div></div>';
      }
    }
    grid.innerHTML = html;
    grid.querySelectorAll('.slot[data-idx]').forEach(function(el){
      el.onclick = function(){
        var idx = parseInt(el.dataset.idx);
        if (el.dataset.act === 'buy') openPickAsset(idx);
        else openUpgAsset(idx);
      };
    });
  }

  function renderBuy(){
    var cat = state.data.catalog || [];
    var u = state.user;
    var html = cat.map(function(a){
      var afford = u.coins >= a.buyCost;
      return '<div class="asset-row">' +
        '<div class="asset-ico">'+ (ASSET_ICON[a.type]||'🌱') +'</div>' +
        '<div class="asset-info"><div class="asset-name">'+escapeHtml(a.name)+'</div><div class="asset-meta">Income: '+fmtNum(a.baseIncome)+' / h</div></div>' +
        '<button class="price-btn" data-buy="'+a.type+'"'+(afford?'':' disabled')+'>🪙 '+fmtNum(a.buyCost)+'</button>' +
      '</div>';
    }).join('');
    var box = document.getElementById('bldBuy');
    box.innerHTML = html || '<div class="empty">No assets</div>';
    box.querySelectorAll('button[data-buy]').forEach(function(b){
      b.onclick = function(){ openPickSlot(b.dataset.buy); };
    });
  }

  function renderUpg(){
    var u = state.user; var slots = u.slots || {};
    // Group by type, list each placed asset upgradable
    var placed = [];
    Object.keys(slots).forEach(function(k){ var s = slots[k]; if (s && s.type) placed.push({ idx:parseInt(k), s:s }); });
    if (!placed.length){ document.getElementById('bldUpg').innerHTML = '<div class="empty">Buy assets first to upgrade them.</div>'; return; }
    placed.sort(function(a,b){ return a.idx - b.idx; });
    var maxLv = state.data.maxAssetLevel || 10;
    var html = placed.map(function(p){
      var name = (state.data.catalog.find(function(c){ return c.type === p.s.type; }) || {}).name || p.s.type;
      var cur = incomeOf(p.s.type, p.s.level);
      if (p.s.level >= maxLv){
        return '<div class="asset-row"><div class="asset-ico">'+(ASSET_ICON[p.s.type]||'🌱')+'</div><div class="asset-info"><div class="asset-name">'+escapeHtml(name)+'</div><div class="asset-meta">Level '+p.s.level+' (Max) — '+fmtNum(cur)+' /h</div></div><button class="price-btn" disabled>MAX</button></div>';
      }
      var nx  = incomeOf(p.s.type, p.s.level + 1);
      var cost= upgradeCostOf(p.s.type, p.s.level);
      var afford = u.coins >= cost;
      return '<div class="asset-row">' +
        '<div class="asset-ico">'+(ASSET_ICON[p.s.type]||'🌱')+'</div>' +
        '<div class="asset-info"><div class="asset-name">'+escapeHtml(name)+'</div><div class="asset-meta">Level '+p.s.level+' &nbsp; '+fmtNum(cur)+' /h → '+fmtNum(nx)+' /h</div></div>' +
        '<button class="price-btn" data-upg="'+p.idx+'"'+(afford?'':' disabled')+'>🪙 '+fmtNum(cost)+'</button>' +
      '</div>';
    }).join('');
    var box = document.getElementById('bldUpg');
    box.innerHTML = html;
    box.querySelectorAll('button[data-upg]').forEach(function(b){
      b.onclick = function(){ doUpgradeAsset(parseInt(b.dataset.upg)); };
    });
  }

  function renderRefs(refs){
    var el = document.getElementById('rfList');
    if (!refs.length){ el.innerHTML = '<div class="empty">No referrals yet</div>'; return; }
    el.innerHTML = refs.map(function(r){
      var av = r.photo ? '<img src="'+r.photo+'" alt="">' : '👤';
      var st = r.hasDeposited ? '<span class="badge ok">Active</span>' : '<span class="badge pend">New</span>';
      return '<div class="hist-row">'+
        '<div style="display:flex;align-items:center;gap:8px"><div class="av" style="width:30px;height:30px;font-size:14px;border:none">'+av+'</div><div><div style="font-weight:700">'+escapeHtml(r.name)+'</div><div style="font-size:11px;color:var(--muted)">'+fmtTon(r.earned)+' TON • '+(r.date||'')+'</div></div></div>'+
        st +
      '</div>';
    }).join('');
  }

  function renderWalletHist(deps, wds){
    var rows = [];
    deps.forEach(function(d){ rows.push({ ts:d.ts, label:'Deposit '+fmtTon(d.amount)+' TON', badge:d.status==='completed'?'ok':'pend', text:d.status==='completed'?'Done':'Pending' }); });
    wds.forEach(function(w){ var cls = w.status==='approved'?'ok':w.status==='rejected'?'err':'pend'; var lbl = w.status==='approved'?'Approved':w.status==='rejected'?'Rejected':'Pending'; rows.push({ ts:w.ts, label:'Withdraw '+fmtTon(w.amtRequested||w.amt)+' TON', badge:cls, text:lbl }); });
    rows.sort(function(a,b){ return b.ts - a.ts; });
    var el = document.getElementById('walletHist');
    if (!rows.length){ el.innerHTML = '<div class="empty">No transactions yet</div>'; return; }
    el.innerHTML = rows.map(function(r){ return '<div class="hist-row"><span>'+r.label+'</span><span class="badge '+r.badge+'">'+r.text+'</span></div>'; }).join('');
  }

  // ── Tick pending ──────────────────────────────────────────────
  function tickPending(){
    if (!state.data) return;
    var u = state.user; var per = state.data.island.incomePerHour;
    if (!per) { document.getElementById('pendCoins').textContent = '0'; return; }
    var cap = state.data.island.offlineCapSec;
    var elapsed = Math.min((Date.now() - u.lastCollectTs)/1000, cap);
    var pend = Math.floor(per * elapsed / 3600);
    document.getElementById('pendCoins').textContent = fmtNum(pend);
    document.getElementById('btnCollect').disabled = pend <= 0;
    state.data.island.pendingCoins = pend;
  }

  // ── Actions ───────────────────────────────────────────────────
  function doCollect(){
    var btn = document.getElementById('btnCollect'); btn.disabled = true;
    api('collect').then(function(res){
      if (!res.success){ btn.disabled = false; alert(res.error || 'Failed'); return; }
      state.user.coins = res.data.coins; state.user.lastCollectTs = Date.now();
      state.data.island.pendingCoins = 0;
      document.getElementById('uCoins').textContent = fmtNum(state.user.coins);
      document.getElementById('pendCoins').textContent = '0';
    }).catch(function(){ btn.disabled = false; });
  }

  function openPickAsset(slotIdx){
    state.currentSlot = slotIdx;
    var cat = state.data.catalog || [];
    var u = state.user;
    var html = '<div class="pick-list">' + cat.map(function(a){
      var afford = u.coins >= a.buyCost;
      return '<div class="asset-row">'+
        '<div class="asset-ico">'+(ASSET_ICON[a.type]||'🌱')+'</div>'+
        '<div class="asset-info"><div class="asset-name">'+escapeHtml(a.name)+'</div><div class="asset-meta">Income: '+fmtNum(a.baseIncome)+' / h</div></div>'+
        '<button class="price-btn" data-pick="'+a.type+'"'+(afford?'':' disabled')+'>🪙 '+fmtNum(a.buyCost)+'</button>'+
      '</div>';
    }).join('') + '</div>';
    openModal('Choose an asset', html);
    document.querySelectorAll('button[data-pick]').forEach(function(b){ b.onclick = function(){ doBuy(b.dataset.pick, state.currentSlot); }; });
  }

  function openPickSlot(type){
    // Build clicked → find first empty slot
    var u = state.user;
    var unlocked = state.data.island.unlockedSlots;
    var slot = -1;
    for (var i = 0; i < unlocked; i++){ if (!(u.slots && u.slots[String(i)])){ slot = i; break; } }
    if (slot < 0){ alert('No empty slot. Upgrade your slots first.'); return; }
    doBuy(type, slot);
  }

  function doBuy(type, slotIdx){
    closeModal();
    api('buyAsset', { type:type, slotId:slotIdx }).then(function(res){
      if (!res.success){ alert(res.error || 'Failed'); return; }
      state.user.coins = res.data.coins; state.user.slots = res.data.slots;
      recomputeIncome(); render();
    });
  }

  function openUpgAsset(slotIdx){
    var u = state.user; var slot = u.slots[String(slotIdx)];
    if (!slot) return;
    var name = (state.data.catalog.find(function(c){ return c.type === slot.type; }) || {}).name || slot.type;
    var maxLv = state.data.maxAssetLevel || 10;
    if (slot.level >= maxLv){ openModal('Max Level', '<div style="text-align:center;padding:10px">'+escapeHtml(name)+' is at max level.</div>'); return; }
    var cur = incomeOf(slot.type, slot.level);
    var nx  = incomeOf(slot.type, slot.level + 1);
    var cost= upgradeCostOf(slot.type, slot.level);
    var afford = u.coins >= cost;
    var html = '<div style="text-align:center;font-size:48px;margin:6px 0">'+(ASSET_ICON[slot.type]||'🌱')+'</div>'+
      '<div style="text-align:center;font-weight:800;margin-bottom:6px">'+escapeHtml(name)+'</div>'+
      '<div style="text-align:center;color:var(--muted);margin-bottom:14px">Level '+slot.level+' → '+(slot.level+1)+'<br><b style="color:var(--ink)">'+fmtNum(cur)+' /h → '+fmtNum(nx)+' /h</b></div>'+
      '<div style="text-align:center;margin-bottom:10px">Cost<br><b style="font-size:18px">🪙 '+fmtNum(cost)+'</b></div>'+
      '<button class="btn" id="mUpgBtn"'+(afford?'':' disabled')+'>Upgrade</button>';
    openModal('Upgrade Asset', html);
    var b = document.getElementById('mUpgBtn'); if (b) b.onclick = function(){ doUpgradeAsset(slotIdx); };
  }

  function doUpgradeAsset(slotIdx){
    closeModal();
    api('upgradeAsset', { slotId:slotIdx }).then(function(res){
      if (!res.success){ alert(res.error || 'Failed'); return; }
      state.user.coins = res.data.coins; state.user.slots = res.data.slots;
      recomputeIncome(); render();
    });
  }

  function openUpgSlots(){
    var nx = state.data.slotUpgrade;
    if (!nx){ openModal('Upgrade Slots', '<div style="text-align:center;padding:10px">Already maxed.</div>'); return; }
    var u = state.user; var afford = u.coins >= nx.cost;
    var html = '<div style="text-align:center;font-size:48px;margin:6px 0">🟩</div>'+
      '<div style="text-align:center;margin-bottom:8px">Slots<br><b style="font-size:18px">'+u.slotCount+' → '+nx.slots+'</b></div>'+
      '<div style="text-align:center;color:var(--muted);margin-bottom:12px">You will get '+(nx.slots - u.slotCount)+' more slots</div>'+
      '<div style="text-align:center;margin-bottom:10px">Cost<br><b style="font-size:18px">🪙 '+fmtNum(nx.cost)+'</b></div>'+
      '<button class="btn" id="mUpgBtn"'+(afford?'':' disabled')+'>Upgrade</button>';
    openModal('Upgrade Slots', html);
    document.getElementById('mUpgBtn').onclick = function(){
      closeModal();
      api('upgradeSlots').then(function(res){
        if (!res.success){ alert(res.error || 'Failed'); return; }
        state.user.coins = res.data.coins; state.user.slotsLvl = res.data.slotsLvl; state.user.slotCount = res.data.slots;
        state.data.island.unlockedSlots = res.data.slots;
        loadState();
      });
    };
  }

  function openUpgOffline(){
    var nx = state.data.offlineUpgrade;
    if (!nx){ openModal('Upgrade Offline', '<div style="text-align:center;padding:10px">Already maxed.</div>'); return; }
    var u = state.user; var afford = u.coins >= nx.cost;
    var html = '<div style="text-align:center;font-size:48px;margin:6px 0">⏳</div>'+
      '<div style="text-align:center;margin-bottom:8px">Offline Time<br><b style="font-size:18px">'+u.offlineHours+'h → '+nx.hours+'h</b></div>'+
      '<div style="text-align:center;color:var(--muted);margin-bottom:12px">You will get '+(nx.hours - u.offlineHours)+' more hours</div>'+
      '<div style="text-align:center;margin-bottom:10px">Cost<br><b style="font-size:18px">🪙 '+fmtNum(nx.cost)+'</b></div>'+
      '<button class="btn" id="mUpgBtn"'+(afford?'':' disabled')+'>Upgrade</button>';
    openModal('Upgrade Offline', html);
    document.getElementById('mUpgBtn').onclick = function(){
      closeModal();
      api('upgradeOffline').then(function(res){
        if (!res.success){ alert(res.error || 'Failed'); return; }
        state.user.coins = res.data.coins; state.user.offlineLvl = res.data.offlineLvl; state.user.offlineHours = res.data.hours;
        loadState();
      });
    };
  }

  function submitDeposit(){
    var amount = parseFloat(document.getElementById('dpAmount').value);
    var hash   = document.getElementById('dpHash').value.trim();
    var msg = document.getElementById('dpMsg'); var btn = document.getElementById('dpBtn');
    msg.innerHTML = '';
    if (!amount || amount <= 0) return showMsg(msg,'err','Enter a valid amount.');
    if (!hash || hash.length < 5) return showMsg(msg,'err','Enter the transaction hash.');
    btn.disabled = true;
    api('deposit', { amount:amount, txHash:hash }).then(function(res){
      btn.disabled = false;
      if (!res.success) return showMsg(msg,'err',res.error||'Failed.');
      showMsg(msg,'ok',res.data.message||'Deposit submitted.');
      document.getElementById('dpAmount').value = ''; document.getElementById('dpHash').value = '';
      loadState();
    }).catch(function(e){ btn.disabled = false; showMsg(msg,'err',e.message); });
  }
  function submitWithdraw(){
    var addr = document.getElementById('wdAddr').value.trim();
    var amount = parseFloat(document.getElementById('wdAmount').value);
    var msg = document.getElementById('wdMsg'); var btn = document.getElementById('wdBtn');
    msg.innerHTML = '';
    if (!addr || addr.length < 10) return showMsg(msg,'err','Enter a valid TON address.');
    if (!amount || amount <= 0) return showMsg(msg,'err','Enter a valid amount.');
    btn.disabled = true;
    api('withdraw', { address:addr, amount:amount }).then(function(res){
      btn.disabled = false;
      if (!res.success) return showMsg(msg,'err',res.error||'Failed.');
      showMsg(msg,'ok','Withdrawal submitted. Net: '+fmtTon(res.data.netAmt)+' TON');
      document.getElementById('wdAmount').value = ''; loadState();
    }).catch(function(e){ btn.disabled = false; showMsg(msg,'err',e.message); });
  }
  function copyInviteLink(){
    var inp = document.getElementById('rfLink'); inp.select(); inp.setSelectionRange(0,99999);
    try { document.execCommand('copy'); alert('Invite link copied!'); }
    catch(_){ navigator.clipboard && navigator.clipboard.writeText(inp.value); }
  }
  function shareInviteLink(){
    var link = document.getElementById('rfLink').value;
    var url = 'https://t.me/share/url?url='+encodeURIComponent(link)+'&text='+encodeURIComponent('Join me on '+TITLE+'!');
    if (window.Telegram && window.Telegram.WebApp && window.Telegram.WebApp.openTelegramLink) window.Telegram.WebApp.openTelegramLink(url);
    else window.open(url, '_blank');
  }

  // ── Helpers ───────────────────────────────────────────────────
  function incomeOf(type, level){ var b = baseIncome(type); return Math.round(b * Math.pow(1.2, Math.max(0, (level||1) - 1))); }
  function upgradeCostOf(type, level){ var ub = upgradeBase(type); return Math.round(ub * Math.pow(1.5, Math.max(0, (level||1) - 1))); }
  function baseIncome(t){ var c = (state.data.catalog||[]).find(function(x){ return x.type===t; }); return c? c.baseIncome : 0; }
  function upgradeBase(t){ return { coconut:100, banana:250, fishing:1000 }[t] || 100; }

  function recomputeIncome(){
    var per = 0; var slots = state.user.slots || {};
    Object.keys(slots).forEach(function(k){ var s = slots[k]; if (s && s.type) per += incomeOf(s.type, s.level); });
    state.data.island.incomePerHour = per;
  }
  function countOccupied(slots){ var n=0; for (var k in (slots||{})) if (slots[k] && slots[k].type) n++; return n; }

  function openModal(title, html){
    document.getElementById('mTitle').textContent = title;
    document.getElementById('mBody').innerHTML = html;
    document.getElementById('modal').classList.add('open');
  }
  function closeModal(){ document.getElementById('modal').classList.remove('open'); }

  function fmtNum(n){ n = parseInt(n) || 0; return n.toLocaleString('en-US'); }
  function fmtTon(n){ n = parseFloat(n) || 0; var s = n.toFixed(4).replace(/\.?0+$/,''); return s || '0'; }
  function escapeHtml(s){ return String(s||'').replace(/[&<>"']/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); }
  function showMsg(el, cls, text){ el.innerHTML = '<div class="msg '+cls+'">'+escapeHtml(text)+'</div>'; }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
